insert into public.settings (key, value, is_public) values ('payments', '{"bankTransfer":{"enabled":true,"label":"Transferencia Bancaria","instructions":"Realizá el pago a nuestra cuenta usando el número de pedido como referencia. El pedido queda En espera hasta validar el pago."},"cash":{"enabled":true,"label":"Efectivo (5% de descuento)","discountPercent":5,"allowedDeliveryKinds":["local_pickup"],"initialOrderStatus":"on_hold"},"mercadopago":{"enabled":false},"card":{"enabled":false}}'::jsonb, false) on conflict (key) do update set value = excluded.value, is_public = excluded.is_public;
insert into public.settings (key, value, is_public) values ('shipping', '{"pickup":{"label":"Retirar por el Local"},"scheduledCaba":{"enabled":true,"label":"HORARIO ESPECIFICO CABA (coordinar horario)","priceCents":1200000},"correoFallbackPackage":{"weightKg":1,"lengthCm":20,"widthCm":15,"heightCm":10},"excludedCities":["general rodriguez","san vicente","canuelas","marcos paz","mariano acosta","burzaco"],"excludedPostcodes":[1723,1727,1748,1814,1852,1865]}'::jsonb, false) on conflict (key) do update set value = excluded.value, is_public = excluded.is_public;
