insert into public.settings (key, value, is_public) values ('faq', '{"items":[{"q":"¿Qué medios de pago aceptan?","a":"Transferencia bancaria y efectivo. El efectivo tiene 5% de descuento y es únicamente al retirar tu pedido por el local. Los pedidos con transferencia quedan En espera hasta que validamos el pago; podés enviarnos el comprobante por WhatsApp."},{"q":"¿Cómo se abonan los envíos?","a":"Todos los envíos (moto y Correo Argentino) se abonan por anticipado, por transferencia bancaria."},{"q":"¿Cuánto demoran los envíos?","a":"CABA y alrededores (moto): si el pago se acredita antes de las 11:30 hs, la entrega es en el día, de 16 a 22 hs. Si no, se entrega el siguiente día hábil.\nResto del país: por Correo Argentino, 2 a 4 días hábiles según la zona."},{"q":"¿Cuánto cuesta el envío en moto?","a":"CABA: $4.000 · Primer cordón: $6.000 · Zona azul: $8.000 · Zona roja: $9.500. El costo exacto se calcula en el checkout según tu código postal y localidad. Si tu zona no tiene cobertura de moto, podés elegir Correo Argentino o retirar por el local."},{"q":"¿Puedo retirar por el local?","a":"Sí, el retiro por el local está disponible para todas las zonas y no tiene costo."},{"q":"¿Cómo consigo precios mayoristas?","a":"Funciona por puntos. Cada perfume árabe suma 1 punto; cada perfume de diseñador suma 2 puntos en la primera compra y 1,5 en re-stock; cada producto de cosmética suma 0,5. Los decants no suman puntos.\nPrimera compra mayorista: 10 puntos. Al confirmarse esa compra, tu cuenta pasa a mayorista.\nRe-stock (cuentas mayoristas): 3 puntos.\nEn el carrito vas a ver cuántos puntos llevás y cuántos te faltan."},{"q":"¿Los perfumes de diseñador tienen stock?","a":"Los perfumes de diseñador se manejan a pedido. Consultanos por WhatsApp desde la ficha del producto y te pasamos disponibilidad y precio."}]}'::jsonb, true) on conflict (key) do update set value = excluded.value, is_public = excluded.is_public;
insert into public.settings (key, value, is_public) values ('catalog', '{"hiddenRootCategories":["electronica"],"onRequestCategories":["disenador-masculinas","disenador-femeninas","fragancias-femeninas-cosmetica"],"hideDesignerPrices":true,"placeholderOnImageError":true,"menu":[{"label":"Inicio","href":"/"},{"label":"Fragancias Masculinas","href":"/product-category/perfumeria/fragancias-masculinas/"},{"label":"Fragancias Femeninas","href":"/product-category/perfumeria/fragancias-femeninas/"},{"label":"Fragancias Kids","href":"/product-category/perfumeria/fragancias-kids/"},{"label":"FAQs","href":"/faq/"},{"label":"Contacto","href":"/contacto/"}]}'::jsonb, true) on conflict (key) do update set value = excluded.value, is_public = excluded.is_public;
